targets.expr:
label_replace(
  (
    max by (instance, mountpoint) (
      1 - node_filesystem_avail_bytes{fstype!~"tmpfs|ramfs|vfat|squashfs|overlay|nsfs|fuse.*", mountpoint!="/nix/store"}
        / node_filesystem_size_bytes
    ) > 0.85
  )
  or (
    (
      label_set(vector(2), "instance", "lotus-land-story:9100", "mountpoint", "/mnt/lotus-land-story")
      or label_set(vector(2), "instance", "legacy-of-lunatic-kingdom:9100", "mountpoint", "/mnt/data")
      or label_set(vector(2), "instance", "mountain-of-faith:9100", "mountpoint", "/mnt/mountain-of-faith")
    )
    unless on (instance, mountpoint) node_filesystem_size_bytes
  )
  or on () label_set(vector(0), "instance", "all"),
  "instance", "$1", "instance", "(.*):\\d+"
)
